<template>
  <div class="flex flex-col gap-6">
    <!-- Group filter. The dashboard's date/region filters are hidden on this tab by the parent —
         neither means anything for a roster. Options come from the response, so a group added
         server-side appears here with its own label and no frontend change. -->
    <div class="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
      <AppMultiComboboxQuery
        :items="groupItems"
        :value="groupFilter"
        property-name="groups"
        placeholder="All groups"
        input-placeholder="Search group..."
        empty-text="No groups found"
        items-plural-name="groups"
        :null-is-all="true"
        :icon="UserCogIcon"
        data-testid="team-group-filter"
      />
    </div>

    <AppLoader v-if="isPendingRoster" subject="team" />
    <AppError v-else-if="rosterError" title="Failed to load team" :error="rosterError" />
    <AppEmpty v-else-if="!sections.length" subject="team members" />

    <div v-else class="grid grid-cols-1 gap-4 lg:grid-cols-[minmax(260px,320px)_1fr]">
      <Card
        class="self-start flex-col overflow-hidden max-h-[calc(100vh-12rem)] lg:flex"
        :class="showProfileOnMobile ? 'hidden' : 'flex'"
      >
        <CardContent class="!p-0 !md:p-0 flex flex-col overflow-hidden flex-1">
          <div
            class="h-14 shrink-0 bg-accent border-b px-4 flex items-center text-accent-foreground text-xs sm:text-sm leading-6 font-medium"
          >
            Name
          </div>
          <div v-if="visibleSections.length" class="flex-1 overflow-y-auto" data-testid="team-roster-list">
            <template v-for="section in visibleSections" :key="section.group">
              <div
                class="sticky top-0 z-10 bg-muted/95 px-4 py-2 text-xs font-semibold uppercase tracking-wide text-muted-foreground backdrop-blur"
              >
                {{ section.label }}
              </div>
              <ul class="divide-y">
                <li v-for="member in section.members" :key="member.id">
                  <!-- A button, not a clickable <li>: selecting a member has to work by keyboard,
                       and this is a public page covered by the a11y suite. -->
                  <button
                    type="button"
                    class="flex w-full items-center gap-3 px-4 py-3 text-left transition-colors hover:bg-muted/50 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring"
                    :class="{ 'bg-muted/70': member.id === selected?.member.id }"
                    :aria-current="member.id === selected?.member.id ? 'true' : undefined"
                    data-testid="team-roster-member"
                    @click="onSelect(member.id)"
                  >
                    <Avatar size="sm">
                      <AvatarImage
                        v-if="member.profile_picture_url"
                        :src="member.profile_picture_url"
                        :alt="username(member)"
                      />
                      <AvatarFallback>{{ initials(member) }}</AvatarFallback>
                    </Avatar>
                    <div class="flex min-w-0 flex-col gap-0.5">
                      <span class="truncate text-sm font-medium">{{ username(member) }}</span>
                      <span class="truncate text-xs text-muted-foreground">
                        {{ member.position ?? section.label }}
                      </span>
                    </div>
                  </button>
                </li>
              </ul>
            </template>
          </div>
          <div v-else class="flex flex-1 items-center justify-center p-6 text-sm text-muted-foreground">
            No team members match the current filters.
          </div>
        </CardContent>
      </Card>

      <Card class="overflow-hidden lg:block" :class="{ hidden: !showProfileOnMobile }">
        <CardContent class="!p-0 !md:p-0">
          <div
            class="h-14 bg-accent border-b px-4 flex items-center gap-2 text-accent-foreground text-xs sm:text-sm leading-6 font-medium"
          >
            <button
              type="button"
              class="-ml-1 flex items-center gap-1 rounded px-1 py-0.5 hover:opacity-70 lg:hidden"
              @click="showProfileOnMobile = false"
            >
              <ChevronLeftIcon class="h-4 w-4" />
              Back
            </button>
            <span>Profile</span>
          </div>
          <div class="flex flex-col gap-6 p-4 py-6 sm:flex-row sm:items-start" data-testid="team-member-profile">
            <img
              v-if="memberPictureUrl"
              :src="memberPictureUrl"
              :alt="memberName"
              class="aspect-square w-full max-w-[380px] shrink-0 rounded-md border object-cover object-top sm:w-96"
            />
            <div
              v-else
              class="aspect-square w-full max-w-[380px] shrink-0 rounded-md border bg-muted flex items-center justify-center text-4xl font-semibold text-muted-foreground sm:w-96"
            >
              {{ selected ? initials(selected.member) : '' }}
            </div>
            <div class="flex flex-1 flex-col gap-3">
              <h3 class="text-2xl font-semibold">{{ memberName }}</h3>
              <Badge variant="default" class="w-fit">{{ memberBadge }}</Badge>
              <Skeleton v-if="isPendingMember" class="h-32 w-full" />
              <AppError v-else-if="memberError" title="Failed to load profile" :error="memberError" />
              <p v-else class="whitespace-pre-line text-base leading-relaxed text-muted-foreground">
                {{ memberData?.bio ?? 'No bio provided yet.' }}
              </p>
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  </div>
</template>

<script setup lang="ts">
import { ChevronLeftIcon, UserCogIcon } from 'lucide-vue-next';
import type { CanvassingProjectTeamRosterItem } from '~/client';
import {
  getCanvassingProjectTeamDashboard,
  getCanvassingProjectTeamMember,
  getPublicCanvassingProjectTeamDashboard,
  getPublicCanvassingProjectTeamMember,
} from '~/client';

interface Props {
  isPublic?: boolean;
  projectId?: string;
  dashboardHash?: string;
}

const props = withDefaults(defineProps<Props>(), {
  isPublic: false,
  projectId: undefined,
  dashboardHash: undefined,
});

const route = useRoute();

// Empty means "all groups" — mirrors the null-is-all combobox contract.
const groupFilter = computed(() => processArrayQueryParameterFromUrl<string>(route.query.groups) ?? []);

const rosterKey = computed(() =>
  props.isPublic
    ? ['public.canvassing.dashboard.team', props.dashboardHash ?? '']
    : ['canvassing.dashboard.team', props.projectId ?? '']
);

const {
  data: rosterData,
  error: rosterError,
  isPending: isPendingRoster,
} = useQuery({
  key: () => rosterKey.value,
  query: () =>
    props.isPublic
      ? getPublicCanvassingProjectTeamDashboard({ path: { public_hash: props.dashboardHash! } })
      : getCanvassingProjectTeamDashboard({ path: { project_id: props.projectId! } }),
  enabled: () => Boolean(props.isPublic ? props.dashboardHash : props.projectId),
});

// The server sends sections already grouped, ordered, and labelled; the filter only removes whole
// sections. Filter options come from the unfiltered response so selecting one never hides the rest.
const sections = computed(() => rosterData.value?.sections ?? []);
const groupItems = computed<SelectItem<string>[]>(() =>
  sections.value.map((section) => ({ value: section.group, name: section.label }))
);
const visibleSections = computed(() => filterRosterSections(sections.value, groupFilter.value));
const visibleEntries = computed(() => flattenRosterSections(visibleSections.value));

const selectedId = computed(() => processArrayQueryParameterFromUrl<string>(route.query.member)?.[0] ?? null);
const selected = computed(() => resolveSelectedEntry(visibleEntries.value, selectedId.value));

const showProfileOnMobile = ref(Boolean(selectedId.value));

async function onSelect(id: string) {
  showProfileOnMobile.value = true;
  await navigateTo({ name: route.name, params: route.params, query: { ...route.query, member: id }, replace: true });
}

const memberKey = computed(() => [...rosterKey.value, 'member', selected.value?.member.id ?? '']);

// No placeholderData: keeping the previous member's bio while a new one loads would render one
// person's text under another's name. A skeleton fills the gap instead.
const {
  data: memberData,
  error: memberError,
  isPending: isPendingMember,
} = useQuery({
  key: () => memberKey.value,
  query: () =>
    props.isPublic
      ? getPublicCanvassingProjectTeamMember({
          path: { public_hash: props.dashboardHash!, user_id: selected.value!.member.id },
        })
      : getCanvassingProjectTeamMember({
          path: { project_id: props.projectId!, user_id: selected.value!.member.id },
        }),
  enabled: () => Boolean(selected.value?.member.id),
});

// Name and badge come from the roster row so they paint immediately; only the bio and the large
// photo wait on the detail request. The group label is a defensive fallback — a roster member always
// has a position, since that is what puts them on the roster.
const memberName = computed(() => (selected.value ? username(selected.value.member) : ''));
const memberBadge = computed(() => selected.value?.member.position ?? selected.value?.groupLabel ?? '');
const memberPictureUrl = computed(() => memberData.value?.profile_picture_url ?? null);

function initials(member: CanvassingProjectTeamRosterItem): string {
  return `${member.first_name.charAt(0)}${member.last_name.charAt(0)}`.toUpperCase();
}
</script>
