<template>
  <div class="flex flex-col gap-6">
    <!-- TOP NAV ROW (internal only) — back on the left; last-updated + share on the right. -->
    <div v-if="!isPublic" class="flex flex-wrap items-center justify-between gap-2">
      <GoBackButton subject="project" :fallback-to="{ name: 'projects-id', params: { id: projectId } }" />
      <div class="flex flex-wrap items-center gap-2">
        <DashboardLastUpdated v-if="createdAtData?.calculated_at" :calculated-at="createdAtData.calculated_at" />
        <PublicLinkDialog v-if="isAdmin" subject="dashboard" />
      </div>
    </div>

    <CanvassingProjectOverviewDashboard
      :is-public
      :project-id
      :dashboard-hash
      :project-start-end-date
      :project-regions
    />

    <FilterTabsNav :items="tabItems" rounded />

    <!-- Date range and regions are meaningless for a roster; the Team tab carries its own filter. -->
    <CanvassingDashboardFilters
      v-if="activeTab !== 'team'"
      :is-public="isPublic"
      :project-id="projectId"
      :params="params"
      :project-start-end-date="projectStartEndDate"
      :project-regions="projectRegions"
    />

    <CanvassingProjectActivityDashboard
      v-if="activeTab === 'overview'"
      :is-public
      :project-id
      :dashboard-hash
      :project-start-end-date
      :map-date-range
      :project-regions
    />
    <CanvassingProjectResponsesDashboard
      v-else-if="activeTab === 'responses'"
      :is-public
      :project-id
      :dashboard-hash
      :project-start-end-date
      :map-date-range
      :project-regions
    />
    <CanvassingProjectTeamDashboard v-else-if="activeTab === 'team'" :is-public :project-id :dashboard-hash />
  </div>
</template>

<script setup lang="ts">
import {
  getCanvassingProjectOverviewDashboard,
  type GetCanvassingProjectActivityDashboardData,
  type ProjectGeneralInfoRegion,
} from '~/client';
import type { NavigationItem } from '~/types/projects';

type CanvassingDashboardTab = 'overview' | 'responses' | 'team';

interface Props {
  isPublic?: boolean;
  projectId?: string;
  dashboardHash?: string;
  projectStartEndDate: { start: string; end: string };
  projectRegions?: ProjectGeneralInfoRegion[];
  /** The tab is part of the path (one page file per tab), so the active tab arrives as a prop. */
  tab?: CanvassingDashboardTab;
}

const props = withDefaults(defineProps<Props>(), {
  isPublic: false,
  projectId: undefined,
  dashboardHash: undefined,
  projectRegions: undefined,
  tab: 'overview',
});

const route = useRoute();
const { isAdmin } = useUserRole();
const timezone = Intl.DateTimeFormat().resolvedOptions().timeZone;

const activeTab = computed<CanvassingDashboardTab>(() => props.tab);

// Tab links target the sibling tab pages, carrying the filter query (dates, regions) across.
const tabTarget = (tab: CanvassingDashboardTab): NavigationItem['to'] => {
  if (props.isPublic) {
    const params = { hash: props.dashboardHash ?? '' };
    if (tab === 'responses') return { name: 'share-project-dashboard-hash-responses', params, query: route.query };
    if (tab === 'team') return { name: 'share-project-dashboard-hash-team', params, query: route.query };
    return { name: 'share-project-dashboard-hash', params, query: route.query };
  }
  const params = { id: props.projectId ?? '' };
  if (tab === 'responses') return { name: 'projects-id-dashboard-responses', params, query: route.query };
  if (tab === 'team') return { name: 'projects-id-dashboard-team', params, query: route.query };
  return { name: 'projects-id-dashboard', params, query: route.query };
};

const tabItems = computed<NavigationItem[]>(() => [
  {
    label: 'Overview',
    to: tabTarget('overview'),
    selected: activeTab.value === 'overview',
  },
  {
    label: 'Responses',
    to: tabTarget('responses'),
    selected: activeTab.value === 'responses',
  },
  {
    label: 'Team',
    to: tabTarget('team'),
    selected: activeTab.value === 'team',
  },
]);

// Filtered params drive the Activity / Responses tabs (public omits per-canvasser filters).
const params = computed(() => {
  const base = {
    start_date: route.query.start_date ? route.query.start_date.toString() : props.projectStartEndDate.start,
    end_date: route.query.end_date ? route.query.end_date.toString() : props.projectStartEndDate.end,
    regions: processArrayQueryParameterFromUrl(route.query.regions),
    timezone,
  };

  const urlParams: GetCanvassingProjectActivityDashboardData['query'] = props.isPublic
    ? base
    : (() => {
        const { subcontractor_company_ids, include_unassigned } = parseSubcontractorCompanyFilter(
          route.query.subcontractor_company_ids
        );
        return {
          ...base,
          canvasser_ids: processArrayQueryParameterFromUrl(route.query.canvasser_ids),
          subcontractor_company_ids,
          include_unassigned,
        };
      })();

  return Object.fromEntries(
    Object.entries(urlParams).filter(([_, value]) => value !== undefined)
  ) as unknown as GetCanvassingProjectActivityDashboardData['query'];
});

const mapDateRange = computed(() => ({
  startDate: params.value.start_date ?? props.projectStartEndDate.start,
  endDate: params.value.end_date ?? props.projectStartEndDate.end,
}));

// The timestamp only renders on the internal dashboard; the key matches
// CanvassingProjectOverviewDashboard's, so the data comes from the shared cache.
const { data: createdAtData } = useQuery({
  key: () => ['canvassing.dashboard.overview', props.projectId ?? '', timezone],
  query: () =>
    getCanvassingProjectOverviewDashboard({
      path: { project_id: props.projectId! },
      query: { timezone },
    }),
  enabled: () => !props.isPublic && !!props.projectId,
});
</script>
