<template>
  <AppLoader v-if="isPendingResponses" subject="dashboard" />
  <AppError v-else-if="responsesError" title="Failed to load dashboard" :error="responsesError" />
  <div v-else-if="responsesData?.charts" class="grid grid-cols-12 gap-4">
    <DashboardChartsCardV2
      :charts="responsesData.charts"
      :loading="isLoadingResponses"
      :params="params"
      :project-id="isPublic ? undefined : projectId"
      :dashboard-id="isPublic ? dashboardHash : undefined"
      :map-date-range="mapDateRange"
      :map-type="mapRoutingType"
    />
  </div>
</template>

<script setup lang="ts">
import type { GetCanvassingProjectResponsesDashboardData, ProjectGeneralInfoRegion } from '~/client';
import { getCanvassingProjectResponsesDashboard, getPublicCanvassingProjectResponsesDashboard } from '~/client';

interface Props {
  isPublic?: boolean;
  projectId?: string;
  dashboardHash?: string;
  projectStartEndDate: { start: string; end: string };
  projectRegions?: ProjectGeneralInfoRegion[];
  mapDateRange: { startDate: string; endDate: string };
}

const props = withDefaults(defineProps<Props>(), {
  isPublic: false,
  projectId: undefined,
  dashboardHash: undefined,
  projectRegions: undefined,
});

const route = useRoute();
const timezone = Intl.DateTimeFormat().resolvedOptions().timeZone;
const mapRoutingType = computed(() => (props.isPublic ? 'public-project' : 'project'));

const params = computed(() => {
  const base = {
    start_date: route.query.start_date ? route.query.start_date.toString() : props.projectStartEndDate.start,
    end_date: route.query.end_date ? route.query.end_date.toString() : props.projectStartEndDate.end,
    regions: processArrayQueryParameterFromUrl(route.query.regions),
    timezone,
  };

  const urlParams: GetCanvassingProjectResponsesDashboardData['query'] = props.isPublic
    ? base
    : (() => {
        const { subcontractor_company_ids, include_unassigned } = parseSubcontractorCompanyFilter(
          route.query.subcontractor_company_ids
        );
        return {
          ...base,
          canvasser_ids: processArrayQueryParameterFromUrl(route.query.canvasser_ids),
          subcontractor_company_ids,
          include_unassigned,
        };
      })();

  return Object.fromEntries(
    Object.entries(urlParams).filter(([_, value]) => value !== undefined)
  ) as unknown as GetCanvassingProjectResponsesDashboardData['query'];
});

const responsesKey = computed(() =>
  props.isPublic
    ? ['public.canvassing.dashboard.responses', props.dashboardHash ?? '', params.value]
    : ['canvassing.dashboard.responses', props.projectId ?? '', params.value]
);

const {
  data: responsesData,
  error: responsesError,
  isLoading: isLoadingResponses,
  isPending: isPendingResponses,
} = useQuery({
  key: () => responsesKey.value,
  query: () =>
    props.isPublic
      ? getPublicCanvassingProjectResponsesDashboard({
          path: { public_hash: props.dashboardHash! },
          query: params,
        })
      : getCanvassingProjectResponsesDashboard({
          path: { project_id: props.projectId! },
          query: params,
        }),
  placeholderData: (previousData) => previousData,
});
</script>
