<template>
  <AppLoader v-if="isPendingActivity" subject="dashboard" />
  <AppError v-else-if="activityError" title="Failed to load dashboard" :error="activityError" />
  <div v-else-if="activityData?.charts" class="grid grid-cols-12 gap-4">
    <DashboardChartsCardV2
      :charts="activityData.charts"
      :loading="isLoadingActivity"
      :params="params"
      :project-id="isPublic ? undefined : projectId"
      :dashboard-id="isPublic ? dashboardHash : undefined"
      :map-date-range="mapDateRange"
      :map-type="mapRoutingType"
    />
  </div>
</template>

<script setup lang="ts">
import type { GetCanvassingProjectActivityDashboardData, ProjectGeneralInfoRegion } from '~/client';
import { getCanvassingProjectActivityDashboard, getPublicCanvassingProjectActivityDashboard } from '~/client';

interface Props {
  isPublic?: boolean;
  projectId?: string;
  dashboardHash?: string;
  projectStartEndDate: { start: string; end: string };
  mapDateRange: { startDate: string; endDate: string };
  projectRegions?: ProjectGeneralInfoRegion[];
}

const props = withDefaults(defineProps<Props>(), {
  isPublic: false,
  projectId: undefined,
  dashboardHash: undefined,
  projectRegions: undefined,
});

const route = useRoute();
const timezone = Intl.DateTimeFormat().resolvedOptions().timeZone;
const mapRoutingType = computed(() => (props.isPublic ? 'public-project' : 'project'));

const params = computed(() => {
  const base = {
    start_date: route.query.start_date ? route.query.start_date.toString() : props.projectStartEndDate.start,
    end_date: route.query.end_date ? route.query.end_date.toString() : props.projectStartEndDate.end,
    regions: processArrayQueryParameterFromUrl(route.query.regions),
    timezone,
  };

  const urlParams: GetCanvassingProjectActivityDashboardData['query'] = props.isPublic
    ? base
    : (() => {
        const { subcontractor_company_ids, include_unassigned } = parseSubcontractorCompanyFilter(
          route.query.subcontractor_company_ids
        );
        return {
          ...base,
          canvasser_ids: processArrayQueryParameterFromUrl(route.query.canvasser_ids),
          subcontractor_company_ids,
          include_unassigned,
        };
      })();

  return Object.fromEntries(
    Object.entries(urlParams).filter(([_, value]) => value !== undefined)
  ) as unknown as GetCanvassingProjectActivityDashboardData['query'];
});

const activityKey = computed(() =>
  props.isPublic
    ? ['public.canvassing.dashboard.activity', props.dashboardHash ?? '', params.value]
    : ['canvassing.dashboard.activity', props.projectId ?? '', params.value]
);

const {
  data: activityData,
  error: activityError,
  isLoading: isLoadingActivity,
  isPending: isPendingActivity,
} = useQuery({
  key: () => activityKey.value,
  query: () =>
    props.isPublic
      ? getPublicCanvassingProjectActivityDashboard({
          path: { public_hash: props.dashboardHash! },
          query: params,
        })
      : getCanvassingProjectActivityDashboard({
          path: { project_id: props.projectId! },
          query: params,
        }),
  placeholderData: (previousData) => previousData,
});
</script>
