import type { CanvassingProjectTeamRosterItem, CanvassingProjectTeamSection } from '~/client';

/**
 * A roster member paired with the section it came from.
 *
 * Sections, their order, and their labels are resolved server-side and rendered as-is — the client
 * holds no copy of the group set, so a group added on the server shows up without a frontend change.
 * This flattening exists only for what works across sections: resolving the selected member and
 * labelling them in the profile pane.
 */
export interface ProjectTeamEntry {
  member: CanvassingProjectTeamRosterItem;
  group: CanvassingProjectTeamSection['group'];
  groupLabel: string;
}

export function flattenRosterSections(sections: CanvassingProjectTeamSection[]): ProjectTeamEntry[] {
  return sections.flatMap((section) =>
    section.members.map((member) => ({ member, group: section.group, groupLabel: section.label }))
  );
}

/**
 * Filter whole sections by group, preserving the server's section and member order. An empty
 * selection means "all groups", mirroring the null-is-all combobox contract.
 */
export function filterRosterSections(
  sections: CanvassingProjectTeamSection[],
  groups: string[]
): CanvassingProjectTeamSection[] {
  return groups.length ? sections.filter((section) => groups.includes(section.group)) : sections;
}

/**
 * Resolve which member the profile pane shows. When the group filter hides the current selection,
 * fall back to the first visible member so the pane never blanks while the list still has rows.
 */
export function resolveSelectedEntry(entries: ProjectTeamEntry[], selectedId: string | null): ProjectTeamEntry | null {
  if (entries.length === 0) return null;
  return entries.find((entry) => entry.member.id === selectedId) ?? entries[0];
}
