<template>
  <AppLoader v-if="isPendingOverview" subject="dashboard" />
  <AppError v-else-if="overviewError" title="Failed to load dashboard" :error="overviewError" />
  <div v-else-if="overviewData?.charts" class="grid grid-cols-12 gap-4">
    <DashboardChartsCardV2
      :charts="overviewData.charts"
      :loading="isLoadingOverview"
      :params="{ timezone: timezone }"
      :project-id="isPublic ? undefined : projectId"
      :dashboard-id="isPublic ? dashboardHash : undefined"
      :map-type="mapRoutingType"
    />
  </div>
</template>

<script setup lang="ts">
import type { ProjectGeneralInfoRegion } from '~/client';
import { getCanvassingProjectOverviewDashboard, getPublicCanvassingProjectOverviewDashboard } from '~/client';

const props = defineProps<{
  isPublic?: boolean;
  projectId?: string;
  dashboardHash?: string;
  projectStartEndDate: { start: string; end: string };
  projectRegions?: ProjectGeneralInfoRegion[];
}>();

const timezone = Intl.DateTimeFormat().resolvedOptions().timeZone;
const mapRoutingType = computed(() => (props.isPublic ? 'public-project' : 'project'));

const identifier = computed(() => (props.isPublic ? props.dashboardHash : props.projectId));

const overviewKey = computed(() =>
  props.isPublic
    ? ['public.canvassing.dashboard.overview', props.dashboardHash ?? '', timezone]
    : ['canvassing.dashboard.overview', props.projectId ?? '', timezone]
);

const {
  data: overviewData,
  error: overviewError,
  isLoading: isLoadingOverview,
  isPending: isPendingOverview,
} = useQuery({
  key: () => overviewKey.value,
  query: () =>
    props.isPublic
      ? getPublicCanvassingProjectOverviewDashboard({
          path: { public_hash: props.dashboardHash! },
          query: { timezone },
        })
      : getCanvassingProjectOverviewDashboard({
          path: { project_id: props.projectId! },
          query: { timezone },
        }),
  placeholderData: (previousData) => previousData,
  enabled: () => !!identifier.value,
});
</script>
